const orderRow = $json || {};
const boutique = $('Info_boutique').item.json || {};
const agentOut = $('AI Agent1').item.json.output || {};
const client = agentOut.client || {};
const produits = agentOut.produits || [];
const commande = agentOut.commande || {};

// Id de commande au format numeric dans la table `commandes`
const orderId = orderRow.id ?? null;

const produitsText = (produits || [])
  .map(p => {
    const nom = p.nom_produit || p.name || '';
    const idProduit = p.id_produit || p.id || '';
    const qty = p.quantite ?? p.quantity ?? '';
    const prix = p.prix_unitaire ?? p.price ?? '';
    return `${nom} (id=${idProduit}) x${qty} @${prix}`;
  })
  .join('; ');

const telephoneClient = client.contact ?? client.telephone ?? '';

const content = `Commande ID: ${orderId}
Boutique: ${boutique.nom_boutique || ''}
Pays: ${boutique.pays || ''}
Ville: ${boutique.ville || ''}
Client: ${client.nom || ''}
Adresse: ${client.adresse || ''}
Telephone: ${telephoneClient}
Statut livraison: ${commande.statut_livraison || ''}
Statut paiement: ${commande.statut_paiement || ''}
Montant total: ${commande.montant_total || ''}
Produits: ${produitsText}`;

const metadata = {
  id_commande: orderId,
  // id_client est stocké dans `commandes`
  id_client: orderRow.id_client ?? ($('If').item.json?.senderId ?? null),
  id_utilisateur: boutique.id_utilisateur ?? null,
  boutique,
  client,
  commande,
  produits,
  order_row: orderRow
};

return [{ json: { content, metadata } }];

const input = $json || {};
const m = input.metadata || {};

const sanitized = {
  id_utilisateur: m.id_utilisateur ?? null,
  id_commande: m.id_commande ?? null,
  id_client: m.id_client ?? null,
  // Garder uniquement les infos nécessaires au SAV + récupération par référence
  client: m.client ?? {},
  commande: m.commande ?? {},
  produits: m.produits ?? [],
  order_row: m.order_row ?? null
};

return [{ json: { content: input.content, metadata: sanitized } }];

